#include "bits/stdc++.h"

#define rep(i, n) for(int i = 0; i < (n); ++i)
#define all(a) (a).begin(), (a).end()

using namespace std;

using ll = long long;
using vl = vector<ll>;
using vi = vector<int>;
const int INFi  = 2e9;

void solve() {
    int n, q; cin >> n >> q;
    vi a(n);
    rep(i, n) cin >> a[i];
    vector<multiset<int>> T(n * 2);
    rep(i, n) {
        for (int j = i + n; j >= 1; j >>= 1) T[j].insert(a[i]);
    }

    rep(_, q) {
        int tp; cin >> tp;
        if (tp == 1) {
            int i, v; cin >> i >> v;
            i--;
            int u = a[i];
            a[i] = v;
            for (i += n; i >= 1; i >>= 1) {
                T[i].erase(T[i].find(u));
                T[i].insert(v);
            }
            continue;
        }
        int l, r; cin >> l >> r;
        l--;
        int v; cin >> v;
        vi segs;
        for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
            if (l & 1) segs.emplace_back(l++);
            if (r & 1) segs.emplace_back(--r);
        }

        sort(all(segs));

        while (true) {
            int mx = -INFi;
            for (auto i : segs) {
                auto it = T[i].upper_bound(v);
                if (it == T[i].begin()) continue;
                mx = max(mx, *prev(it));
            }
            if (mx == -INFi) break;
            v %= mx;
        }

        cout << v << '\n';
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    int t = 1;
    // cin >> t;
    while (t--) {
        solve();
    }
    return 0;
}
